
(function(){
 const $=id=>document.getElementById(id); const esc=v=>String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
 const norm=v=>String(v??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim();
 const money=n=>'$'+Number(n||0).toLocaleString('es-CO'); const nval=v=>Number(String(v||'').replace(/[^0-9]/g,''))||0;
 let editId=null, selectedGiftId=null;
 function groups(){return Array.isArray(window.LIFT_PUBLIC_VARIANT_GROUPS)?window.LIFT_PUBLIC_VARIANT_GROUPS:[]}
 function groupForProduct(id){return groups().find(g=>(g.lift_producto_variantes||[]).some(v=>v.activo!==false&&String(v.producto_id)===String(id)))||null}
 function variants(g){return (g?.lift_producto_variantes||[]).filter(v=>v.activo!==false).sort((a,b)=>Number(a.orden||0)-Number(b.orden||0))}
 function product(id){return (window.PRODUCTS||PRODUCTS||[]).find(p=>String(p.id)===String(id))||null}
 function variantProduct(v){return product(v?.producto_id)}
 function flavor(v){return String(v?.sabor||variantProduct(v)?.flavor||'Variación').trim()}
 async function persist(){if(typeof window.liftCloudSaveConfig!=='function')throw new Error('No está disponible el guardado de ofertas en Supabase.');await window.liftCloudSaveConfig('weekly_offers',WEEKLY_OFFERS)}
 function giftProduct(o){return o?.giftProductId!=null?product(o.giftProductId):null}
 function giftVariant(o){if(!o?.giftVariantId)return null;const gp=giftProduct(o),g=gp?groupForProduct(gp.id):null;return variants(g).find(v=>String(v.id)===String(o.giftVariantId))||null}
 function giftLabel(o){const gp=giftProduct(o);if(!gp)return '';const gv=giftVariant(o);const qty=Math.max(1,Number(o.giftQty||1));return `${qty>1?qty+' × ':''}${gp.name||'Producto'}${gv?' · '+flavor(gv):o.giftChoice?' · sabor a elección':''}`}
 window.liftOfferGiftLabel=giftLabel;
 function offerIdsForScope(baseId){const g=groupForProduct(baseId);if(!g)return [String(baseId)];const mode=$('liftOfferScope')?.value||'one';if(mode==='all')return variants(g).map(v=>String(v.producto_id));if(mode==='selected')return [...document.querySelectorAll('[name="liftOfferVariantCheck"]:checked')].map(x=>String(x.value));return [String(baseId)]}
 function renderVariantChecks(g,currentId){const vv=variants(g);if(!vv.length)return '';return `<div id="liftOfferVariantChecks" class="liftGiftVariants" style="display:none">${vv.map(v=>`<label class="liftGiftVariant"><input type="checkbox" name="liftOfferVariantCheck" value="${esc(v.producto_id)}" ${String(v.producto_id)===String(currentId)?'checked':''}> ${esc(flavor(v))}</label>`).join('')}</div>`}
 function giftVariantOptions(g,o){if(!g)return '';const vv=variants(g);return `<label class="liftGiftField full">Sabor del regalo<select id="liftGiftVariant"><option value="">El cliente elige sabor</option>${vv.map(v=>`<option value="${esc(v.id)}" ${String(o?.giftVariantId||'')===String(v.id)?'selected':''}>${esc(flavor(v))}</option>`).join('')}</select></label>`}
 function selectedGiftHTML(o){const gp=selectedGiftId?product(selectedGiftId):giftProduct(o);if(!gp)return '<div class="lafNote">Sin producto de regalo seleccionado.</div>';const gg=groupForProduct(gp.id);return `<div class="liftGiftSelected"><img src="${esc(gp.image||'')}" onerror="this.style.visibility='hidden'"><div><b>${esc(gp.name||'Producto')}</b><small>${esc(gp.brand||'')}${gp.presentation?' · '+esc(gp.presentation):''}${gg?' · '+variants(gg).length+' sabores':''}</small></div><button class="lafBtn danger" type="button" onclick="liftClearGiftProduct()">Quitar</button></div><div id="liftGiftVariantSlot" class="liftGiftGrid" style="margin-top:9px">${giftVariantOptions(gg,o)}</div>`}
 window.liftOpenGiftOfferEditor=function(id){editId=String(id);const p=product(id);if(!p)return;const o=WEEKLY_OFFERS?.[id]||{};selectedGiftId=o.giftProductId!=null?String(o.giftProductId):null;const g=groupForProduct(id);$('liftGiftOfferProduct').textContent=(p.name||'Producto')+(p.flavor?' · '+p.flavor:'');$('liftGiftOfferEditorBody').innerHTML=`<div class="liftGiftGrid"><label class="liftGiftField">Precio promocional<input id="liftOfferPrice" inputmode="numeric" value="${o.price?Number(o.price).toLocaleString('es-CO'):''}"></label><label class="liftGiftField">Oferta hasta<input id="liftOfferDate" type="date" value="${o.promoUntil?String(o.promoUntil).slice(0,10):''}"></label>${g?`<label class="liftGiftField full">Aplicar promoción a<select id="liftOfferScope" onchange="liftOfferScopeChanged()"><option value="one">Solo ${esc(p.flavor||'esta variación')}</option><option value="all">Todos los sabores del grupo</option><option value="selected">Seleccionar sabores</option></select></label><div class="liftGiftField full">${renderVariantChecks(g,id)}</div>`:''}</div><div class="liftGiftSection"><h4>Producto de regalo (opcional)</h4><div class="lafNote">Busca un producto del catálogo. Si el regalo tiene sabores, puedes fijar uno o dejar que el cliente lo elija.</div><label class="liftGiftField full" style="margin-top:8px">Buscar producto<input id="liftGiftSearch" placeholder="Ej. C4, creatina, pre entreno..." oninput="liftGiftSearch()"></label><div id="liftGiftSearchResults" class="liftGiftSearchResults" style="display:none"></div><div id="liftGiftSelectedSlot">${selectedGiftHTML(o)}</div><div class="liftGiftGrid" style="margin-top:9px"><label class="liftGiftField">Cantidad de regalo<input id="liftGiftQty" inputmode="numeric" value="${Math.max(1,Number(o.giftQty||1))}"></label></div></div><div class="liftGiftActions"><button class="lafBtn" type="button" onclick="liftCloseGiftOfferEditor()">Cancelar</button><button class="lafBtn primary" type="button" onclick="liftSaveGiftOffer()">Guardar oferta</button></div>`;$('liftGiftOfferModal').classList.add('open');$('liftGiftOfferModal').setAttribute('aria-hidden','false')}
 window.liftCloseGiftOfferEditor=function(){$('liftGiftOfferModal')?.classList.remove('open');$('liftGiftOfferModal')?.setAttribute('aria-hidden','true');editId=null;selectedGiftId=null}
 window.liftOfferScopeChanged=function(){const el=$('liftOfferVariantChecks');if(el)el.style.display=$('liftOfferScope')?.value==='selected'?'flex':'none'}
 window.liftGiftSearch=function(){const q=norm($('liftGiftSearch')?.value);const box=$('liftGiftSearchResults');if(!box)return;if(q.length<2){box.style.display='none';box.innerHTML='';return}const seen=new Set(),rows=[];for(const p of (window.PRODUCTS||PRODUCTS||[])){if(!norm([p.name,p.brand,p.presentation,p.flavor].join(' ')).includes(q))continue;const g=groupForProduct(p.id);const key=g?'g:'+g.id:'p:'+p.id;if(seen.has(key))continue;seen.add(key);const base=g?variantProduct(variants(g)[0])||p:p;rows.push({p:base,g});if(rows.length>=25)break}box.innerHTML=rows.map(({p,g})=>`<div class="liftGiftSearchItem"><img src="${esc(g?.imagen||p.image||'')}" onerror="this.style.visibility='hidden'"><div><b>${esc(g?.nombre||p.name||'')}</b><small>${esc(g?.marca||p.brand||'')}${(g?.presentacion||p.presentation)?' · '+esc(g?.presentacion||p.presentation):''}${g?' · '+variants(g).length+' sabores':''}</small></div><button class="lafBtn" type="button" onclick="liftSelectGiftProduct(${Number(p.id)})">Elegir</button></div>`).join('')||'<div class="lafNote" style="padding:10px">Sin resultados.</div>';box.style.display='block'}
 window.liftSelectGiftProduct=function(id){selectedGiftId=String(id);const o=WEEKLY_OFFERS?.[editId]||{};$('liftGiftSelectedSlot').innerHTML=selectedGiftHTML(o);$('liftGiftSearchResults').style.display='none';$('liftGiftSearch').value=''}
 window.liftClearGiftProduct=function(){selectedGiftId=null;$('liftGiftSelectedSlot').innerHTML='<div class="lafNote">Sin producto de regalo seleccionado.</div>'}
 window.liftSaveGiftOffer=async function(){if(!editId)return;const p=product(editId);const price=nval($('liftOfferPrice')?.value),date=$('liftOfferDate')?.value;if(!price){alert('Escribe el precio de oferta.');return}const ids=offerIdsForScope(editId);if(!ids.length){alert('Selecciona al menos un sabor.');return}const gp=selectedGiftId?product(selectedGiftId):null;let giftVariantId=$('liftGiftVariant')?.value||null;const qty=Math.max(1,nval($('liftGiftQty')?.value)||1);const template={price,promoUntil:date?date+'T23:59:59-05:00':'2099-12-31T23:59:59-05:00',gift:!!gp,giftProductId:gp?Number(gp.id):null,giftVariantId:gp&&giftVariantId?Number(giftVariantId):null,giftChoice:!!(gp&&groupForProduct(gp.id)&&!giftVariantId),giftQty:qty};const backup={};ids.forEach(id=>{backup[id]=WEEKLY_OFFERS[id]?{...WEEKLY_OFFERS[id]}:null;WEEKLY_OFFERS[id]={...(WEEKLY_OFFERS[id]||{}),...template}});try{await persist();if(typeof refresh==='function')refresh();if(typeof window.lafRenderOffers==='function')window.lafRenderOffers();liftCloseGiftOfferEditor()}catch(e){ids.forEach(id=>{if(backup[id])WEEKLY_OFFERS[id]=backup[id];else delete WEEKLY_OFFERS[id]});alert('No se pudo guardar la oferta en Supabase: '+(e.message||e))}}
 const baseRender=window.lafRenderOffers;
 window.lafRenderOffers=function(){const input=$('lafOfferSearch');const q=norm(input?.value);const all=(window.PRODUCTS||PRODUCTS||[]);const offered=all.filter(p=>(!q||norm([p.name,p.brand,p.flavor].join(' ')).includes(q))&&WEEKLY_OFFERS?.[p.id]);const rest=all.filter(p=>(!q||norm([p.name,p.brand,p.flavor].join(' ')).includes(q))&&!WEEKLY_OFFERS?.[p.id]).slice(0,40);const a=[...offered,...rest].slice(0,150);const box=$('lafOfferList');if(!box)return;box.innerHTML=a.map(p=>{const o=WEEKLY_OFFERS?.[p.id]||null;const g=groupForProduct(p.id);const gl=o?giftLabel(o):'';return `<div class="lafOfferRow"><div><b style="font-size:11px">${esc(p.name)}</b><div class="lafMeta">${p.flavor?'Sabor: '+esc(p.flavor)+' · ':''}Detal ${money(p.price)}${g?' · grupo de '+variants(g).length+' sabores':''}</div>${gl?`<div class="liftOfferGiftText">🎁 ${esc(gl)}</div>`:''}</div><input class="lafPrice" id="lafo_${esc(p.id)}" placeholder="Precio oferta" value="${o?Number(o.price||0).toLocaleString('es-CO'):''}"><input class="lafPrice" type="date" id="lafod_${esc(p.id)}" value="${o?.promoUntil?String(o.promoUntil).slice(0,10):''}"><div style="display:flex;gap:5px"><button class="liftGiftOfferBtn" type="button" onclick="liftOpenGiftOfferEditor(${Number(p.id)})">${o?'Editar':'Configurar'}</button>${o?`<button class="lafBtn danger" type="button" onclick="liftRemoveOfferV2(${Number(p.id)})">Quitar</button>`:''}</div></div>`}).join('')};
 window.liftRemoveOfferV2=async function(id){const backup=WEEKLY_OFFERS[id]?{...WEEKLY_OFFERS[id]}:null;delete WEEKLY_OFFERS[id];try{await persist();if(typeof refresh==='function')refresh();window.lafRenderOffers()}catch(e){if(backup)WEEKLY_OFFERS[id]=backup;alert('No se pudo quitar la oferta en Supabase: '+(e.message||e))}}
 // Texto de regalo en tarjeta y demás superficies que reutilizan offerDetails.
 if(typeof window.offerDetails==='function'||typeof offerDetails==='function'){
   const old=offerDetails; offerDetails=function(p){const html=old(p);const o=typeof offerOf==='function'?offerOf(p):null;const label=giftLabel(o);return html+(label?`<div class="liftGiftTextOnly">🎁 Regalo: ${esc(label)}</div>`:'')}; window.offerDetails=offerDetails;
 }
 function activeProductForDetail(){let id=window.currentProductId;const g=id?groupForProduct(id):null;if(g){const vid=window.LIFT_SELECTED_GROUP_VARIANT?.[String(g.id)];const v=variants(g).find(x=>String(x.id)===String(vid))||variants(g)[0];if(v)id=v.producto_id}return product(id)}
 window.liftRenderGiftInDetail=function(){const info=document.querySelector('#liftMonoOff .liftMonoInfo');if(!info)return;info.querySelector('#liftGiftDetailBlock')?.remove();const p=activeProductForDetail(),o=p&&typeof offerOf==='function'?offerOf(p):null,gp=giftProduct(o);if(!gp)return;const gv=giftVariant(o),gg=groupForProduct(gp.id),img=String(gv?.imagen||variantProduct(gv)?.image||gg?.imagen||gp.image||'');const label=giftLabel(o);const block=document.createElement('div');block.id='liftGiftDetailBlock';block.className='liftGiftDetail';block.innerHTML=`<img src="${esc(img)}" alt="${esc(label)}" onerror="this.style.display='none'"><div><div class="liftGiftDetailTitle">🎁 REGALO INCLUIDO</div><div class="liftGiftDetailName">${esc(label)}</div><div class="liftGiftDetailMeta">${esc(gp.brand||gg?.marca||'')}${gp.presentation||gg?.presentacion?' · '+esc(gp.presentation||gg?.presentacion):''}${o?.giftChoice?' · Elige sabor al confirmar':''}</div></div>`;const price=info.querySelector('.liftMonoPriceArea');price?.insertAdjacentElement('afterend',block)}
 if(typeof window.liftSelectGroupVariant==='function'){const oldSel=window.liftSelectGroupVariant;window.liftSelectGroupVariant=function(gid,vid){const r=oldSel.apply(this,arguments);setTimeout(window.liftRenderGiftInDetail,0);return r}}
 const obs=new MutationObserver(()=>{if(document.querySelector('#liftMonoOff.open .liftMonoInfo'))setTimeout(window.liftRenderGiftInDetail,0)});obs.observe(document.body,{subtree:true,childList:true});
 // Tras cargar grupos o entrar a Ofertas, repinta para mostrar contexto de sabores.
 setTimeout(()=>{try{window.lafRenderOffers?.()}catch(e){}},1200);
})();
